from flask import Flask, request, jsonify
import json

app = Flask(__name__)

# In-memory storage for students
students = []

# In-memory storage for attendance records
attendance_records = []

@app.route('/students', methods=['GET'])
def get_students():
    """Get all students."""
    return jsonify(students)

@app.route('/students', methods=['POST'])
def add_student():
    """Add a new student."""
    data = request.get_json()

    if not data or 'name' not in data:
        return jsonify({'error': 'Name is required'}), 400

    # Check if student already exists
    if any(s['name'] == data['name'] for s in students):
        return jsonify({'error': 'Student already exists'}), 409

    student = {
        'id': len(students) + 1,
        'name': data['name']
    }
    students.append(student)

    return jsonify(student), 201

@app.route('/attendance/<student_id>', methods=['POST'])
def mark_attendance(student_id):
    """Mark attendance for a student."""
    data = request.get_json()

    # Validate student exists
    student = next((s for s in students if s['id'] == student_id), None)
    if not student:
        return jsonify({'error': 'Student not found'}), 404

    # Validate required fields
    if not data or 'date' not in data or 'status' not in data:
        return jsonify({'error': 'Date and status are required'}), 400

    # Validate status is valid
    if data['status'] not in ['present', 'absent', 'late']:
        return jsonify({'error': 'Status must be present, absent, or late'}), 400

    # Validate date format (YYYY-MM-DD)
    date = data['date']
    try:
        year, month, day = map(int, date.split('-'))
        if not (1 <= month <= 12 and 1 <= day <= 31):
            return jsonify({'error': 'Invalid date format'}), 400
    except ValueError:
        return jsonify({'error': 'Invalid date format'}), 400

    # Create attendance record
    record = {
        'id': len(attendance_records) + 1,
        'student_id': student_id,
        'student_name': student['name'],
        'date': date,
        'status': data['status']
    }
    attendance_records.append(record)

    return jsonify(record), 201

@app.route('/attendance/<student_id>', methods=['GET'])
def get_attendance(student_id):
    """Get attendance records for a student."""
    student = next((s for s in students if s['id'] == student_id), None)
    if not student:
        return jsonify({'error': 'Student not found'}), 404

    records = [r for r in attendance_records if r['student_id'] == student_id]
    return jsonify(records)

@app.route('/attendance', methods=['GET'])
def get_all_attendance():
    """Get all attendance records."""
    return jsonify(attendance_records)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)
